Contract AutomatedTellerMachineSystem::ejectCard(): Boolean {

            precondition:
          self.PasswordValidated = true and self.CardIDValidated = true and self.InputCard.oclIsUndefined() = false and self.InputCard.CardStatus.oclIsTypeOf(CardStatus) and self.InputCard.Catalog.oclIsTypeOf(CardCatalog)

            postcondition:
          self.IsDeposit = false and self.DepositedNumber = 0 and result = true

        }

Contract AutomatedTellerMachineSystem::ejectCard(): Boolean {

            precondition:
          self.PasswordValidated = true and self.CardIDValidated = true and self.InputCard.oclIsUndefined() = false and self.InputCard.CardStatus.oclIsTypeOf(CardStatus) and self.InputCard.Balance >= 0

            postcondition:
          let newBalance:Real in newBalance = self.InputCard.Balance + self.DepositedNumber and self.InputCard.Balance = newBalance and self.IsDeposit = true and result = true

        }

Contract AutomatedTellerMachineSystem::ejectCard(): Boolean {

            precondition:
          self.PasswordValidated = true and self.CardIDValidated = true and self.InputCard.oclIsUndefined() = false and self.InputCard.CardStatus.oclIsTypeOf(CardStatus) and self.InputCard.Balance >= 0

            postcondition:
          self.IsDeposit = false and self.DepositedNumber = 0 and result = true

        }

Contract ProcessSaleService::makeNewSale(): Boolean {
          definition:
          newSale:Sale = Sale.allInstance()->any(s | s.IsComplete = false), storeObs:Set(Store) = Store.allInstance()->select(st | st.IsOpened = true)

            precondition:
          newSale.oclIsUndefined() = false and storeObs.isEmpty() = false

            postcondition:
          let newSale:Sale in newSale.oclIsNew() and newSale.Belongedstore = storeObs->any(s | true) and newSale.IsComplete = false and newSale.IsReadytoPay = false and result = newSale.oclIsNew()

        }

Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          self.countDownSuspensionDay.oclIsUndefined() = false

            postcondition:
          let updatedUsers:Set(User) = User.allInstance()->select(u | u.SuspensionDays > 0) in updatedUsers->forAll(u:User | u.SuspensionDays = u.SuspensionDays - 1) and let zeroDayUsers:Set(User) = User.allInstance()->select(u | u.SuspensionDays = 0 and u.BorrowStatus <> BorrowStatus::SUSPEND) in zeroDayUsers->forAll(u:User | u.BorrowStatus = BorrowStatus::SUSPEND) and result = true

        }

Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          self.users->forAll(u:User | u.SuspensionDays >= 0)

            postcondition:
          self.users->forAll(u:User | u.SuspensionDays = if u.SuspensionDays > 0 then u.SuspensionDays - 1 else 0 endif) and result = true

        }

Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          self.userID <> null and self.userList->select(u : User | u.UserID = self.userID)->notEmpty()

            postcondition:
          self.userList->select(u : User | u.UserID = self.userID)->forAll(u : User | u.SuspensionDays > 0 implies u.SuspensionDays = u.SuspensionDays - 1 and u.BorrowStatus = if u.SuspensionDays - 1 = 0 then BorrowStatus::SUSPEND else u.BorrowStatus endif) and result = true

        }

Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          users:Set(User) = User.allInstance()->select(u | u.SuspensionDays > 0)

            postcondition:
          users->forAll(u:User | u.SuspensionDays = u.SuspensionDays - 1) and result = true

        }

Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          self.userID <> null and self.userList->select(u : User | u.UserID = self.userID)->notEmpty()

            postcondition:
          self.userList->select(u : User | u.UserID = self.userID)->forAll(u : User | u.SuspensionDays = u.SuspensionDays - 1 and if u.SuspensionDays <= 0 then u.BorrowStatus = BorrowStatus::SUSPEND else u.BorrowStatus = BorrowStatus::NORMAL endif) and result = true

        }

