Contract SearchBook::searchBookByBarCode(barcode:String): Set(Book) {
          definition:
          bookCopy:BookCopy = BookCopy.allInstance()->any(bc | bc.Barcode = barcode), resultSet:Set(Book) = Set{}

            precondition:
          bookCopy.oclIsUndefined() = false and barcode <> ''

            postcondition:
          resultSet = if bookCopy.oclIsUndefined() = false then Set{bookCopy.BookBelongs} else Set{} endif and result = resultSet

        }

Contract SubmitLoanRequestModule::calculateScore(): Integer {

            precondition:
          self.CurrentLoanRequest.oclIsUndefined() = false and self.CurrentLoanRequest.Status = LoanRequestStatus::SUBMITTED

            postcondition:
          self.CurrentLoanRequest.CreditScore = self.CurrentLoanRequest.Income * 10 + self.CurrentLoanRequest.LoanAmount / 1000 and result = self.CurrentLoanRequest.CreditScore

        }

